corrected_code:
router.post('/webhooks/shopify/orders-cancelled', async (req, res) => {
  const hmacHeader = req.headers['x-shopify-hmac-sha256'];
  const generatedHash = crypto.createHmac('sha256', process.env.SHOPIFY_API_SECRET)
    .update(req.rawBody, 'utf8')
    .digest('base64');

  if (generatedHash !== hmacHeader) {
    return res.status(401).send('HMAC validation failed');
  }

  const shopDomain = req.headers['x-shopify-shop-domain'];
  const merchant = await Merchant.findOne({ shopifyDomain: shopDomain });
  if (!merchant) {
    return res.status(403).send('Shop domain not recognized');
  }

  const orderData = req.body;
  const targetWarehouseId = orderData.note_attributes?.find(a => a.name === 'restock_warehouse')?.value;

  const warehouse = await Warehouse.findOne({ id: targetWarehouseId, merchantId: merchant.id });
  if (!warehouse) {
    return res.status(400).send('Target warehouse does not belong to verified merchant store');
  }

  for (const item of orderData.line_items) {
    await db.query(
      'UPDATE warehouse_stocks SET quantity = quantity + $1 WHERE sku = $2 AND warehouse_id = $3',
      [item.quantity, item.sku, warehouse.id]
    );
  }
  return res.status(200).json({ status: 'inventory_restocked' });
});
